import{_ as n,o as e,c as a,ai as p}from"./chunks/framework.XEs52zTF.js";const u=JSON.parse('{"title":"从零实现的八个实验","description":"","frontmatter":{"title":"从零实现的八个实验"},"headers":[],"relativePath":"exercises.md","filePath":"exercises.md"}'),t={name:"exercises.md"};function i(r,s,c,l,o,d){return e(),a("div",null,[...s[0]||(s[0]=[p(`<h1 id="从空文件到完整编译器-8-个可验收实验" tabindex="-1">从空文件到完整编译器：8 个可验收实验 <a class="header-anchor" href="#从空文件到完整编译器-8-个可验收实验" aria-label="Permalink to &quot;从空文件到完整编译器：8 个可验收实验&quot;">​</a></h1><p>这些实验以 <code>src/sprout.cpp</code> 为最终参考实现。先在自己的草稿文件中完成当前阶段，再与同名类对照。每个实验都有输入、观察点和验收标准；实验简化不改变最终语言规范。完整测试可先只挑选相关用例，不要求第一天就通过全套。</p><h2 id="实验-1-让字符流变成-token-流" tabindex="-1">实验 1：让字符流变成 Token 流 <a class="header-anchor" href="#实验-1-让字符流变成-token-流" aria-label="Permalink to &quot;实验 1：让字符流变成 Token 流&quot;">​</a></h2><p><strong>先实现：</strong> <code>Pos</code>、<code>Token</code>、<code>Lexer::peek/take/scan</code>，再写一个只扫描并打印 Token 的 <code>main</code>。测试源字符串必须由一个具名 <code>std::string</code> 保存，不能把 <code>Lexer</code> 持有的引用指向临时字符串。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fn main() -&gt; int { let letter = 12; print(letter &gt;= 10); return 0; }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>逐项检查：<code>letter</code> 是一个 id，不应被拆成关键字 <code>let</code> 和剩余字符；<code>&gt;=</code> 是一个 Token；<code>-&gt;</code> 是一个 Token；最后存在 EOF。把字符串后面加 <code>// 中文注释</code>，结果除 EOF 列位置外应不变。加单个 <code>&amp;</code> 应报未知字符。</p><p><strong>验收：</strong> 每个 Token 都有从 1 开始的行列号；输入末尾恰好停在数字或标识符后也不越界。当前完整实现可用 <code>sprout --tokens file.spr</code> 作为结果对照。</p><p><strong>自测题：</strong> 若先判断关键字 <code>let</code> 再继续读标识符，<code>letter</code> 会怎样？为什么关键字识别应放在完整拼写读完以后？</p><h2 id="实验-2-构建表达式树-先不执行" tabindex="-1">实验 2：构建表达式树，先不执行 <a class="header-anchor" href="#实验-2-构建表达式树-先不执行" aria-label="Permalink to &quot;实验 2：构建表达式树，先不执行&quot;">​</a></h2><p><strong>先实现：</strong> <code>Expr</code> 与 <code>Parser::primary/expression</code>。最小阶段只支持整数、括号、四则运算。下面的结构是抽象树示意，不是 Token 顺序：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 + 2 * 3       20 - 5 - 2</span></span>
<span class="line"><span>    +               -</span></span>
<span class="line"><span>   / \\             / \\</span></span>
<span class="line"><span>  1   *           -   2</span></span>
<span class="line"><span>     / \\         / \\</span></span>
<span class="line"><span>    2   3       20  5</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><code>expression(min)</code> 先读左侧，再决定当前运算符能否绑定。右侧调用 <code>expression(当前优先级 + 1)</code>，使同级运算符留给外层循环，从而左结合。可将 <code>+1</code> 暂时删去，比较 <code>20-5-2</code> 的树形，观察它变成 <code>20-(5-2)</code>。</p><p><strong>验收：</strong> <code>1+2*3</code> 的根是 <code>+</code>，其右子节点为 <code>*</code>；<code>(1+2)*3</code> 的根是 <code>*</code>。缺右括号时，错误位置指向实际遇到的 Token。网站示意与完整 <code>--ast</code> 输出相比会省略语句节点和类型标记。</p><h2 id="实验-3-从语法树走到-有意义的程序" tabindex="-1">实验 3：从语法树走到“有意义的程序” <a class="header-anchor" href="#实验-3-从语法树走到-有意义的程序" aria-label="Permalink to &quot;实验 3：从语法树走到“有意义的程序”&quot;">​</a></h2><p><strong>先实现：</strong> 块、变量声明、赋值、符号表；随后加类型检查。符号表不要只用一个全局 map，应使用 <code>vector&lt;map&lt;string, Symbol&gt;&gt;</code> 表示作用域栈。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fn main() -&gt; int {</span></span>
<span class="line"><span>    let x = 10;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        let x = x + 1;</span></span>
<span class="line"><span>        print(x);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    print(x);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>分析内层声明时，先检查初始化表达式，再插入新符号。因此其右侧读取外层 <code>x</code>。最后两个声明应有不同槽号。将内层 <code>let</code> 改为 <code>x = x + 1;</code>，此时不创建新槽位，而是写外层槽。</p><p><strong>验收：</strong> <code>let x=x;</code> 在没有外层 x 时拒绝；同块 <code>let x=1; let x=2;</code> 拒绝；<code>let x=1; x=true;</code> 拒绝。<code>if(1)</code> 拒绝，因为 int 不能隐式转 bool。完整实现用 <code>--check</code> 验收这些静态错误。</p><h2 id="实验-4-用栈机器完成第一个编译闭环" tabindex="-1">实验 4：用栈机器完成第一个编译闭环 <a class="header-anchor" href="#实验-4-用栈机器完成第一个编译闭环" aria-label="Permalink to &quot;实验 4：用栈机器完成第一个编译闭环&quot;">​</a></h2><p><strong>先实现：</strong> <code>Instruction</code>、<code>Generator</code> 的 PUSH/算术/PRINT/RET 和 VM。不要直接遍历 AST 求值；先生成指令，再让 VM 只读指令。</p><p>对以下完整程序：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fn main() -&gt; int { print(1 + 2 * 3); return 0; }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>忽略源位置，字节码应为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0 PUSH 1</span></span>
<span class="line"><span>1 PUSH 2</span></span>
<span class="line"><span>2 PUSH 3</span></span>
<span class="line"><span>3 *</span></span>
<span class="line"><span>4 +</span></span>
<span class="line"><span>5 PRINT_INT</span></span>
<span class="line"><span>6 PUSH 0</span></span>
<span class="line"><span>7 RET</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>手工跟踪：</strong> 栈从 <code>[]</code> 到 <code>[1]</code>、<code>[1,2]</code>、<code>[1,2,3]</code>、<code>[1,6]</code>、<code>[7]</code>、<code>[]</code>。实现二元算术时先弹右值，再弹左值；用 <code>8-3</code> 验证顺序，不能只用加法测试。</p><p><strong>验收：</strong> <code>sprout file.spr</code> 输出 7。<code>sprout --bytecode file.spr</code> 只展示指令，不执行，也不打印 7。每条指令保留对应源位置，运行时除零能回到原来的运算符。</p><h2 id="实验-5-分支、循环与跳转回填" tabindex="-1">实验 5：分支、循环与跳转回填 <a class="header-anchor" href="#实验-5-分支、循环与跳转回填" aria-label="Permalink to &quot;实验 5：分支、循环与跳转回填&quot;">​</a></h2><p><strong>先实现：</strong> LOAD/STORE/JZ/JMP。JZ 消耗栈顶条件，条件为 false 才跳转。第一次生成 JZ 时目标还未知，先写 0 占位，再在分支体生成完成后回填。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fn main() -&gt; int {</span></span>
<span class="line"><span>    let i = 0;</span></span>
<span class="line"><span>    while (i &lt; 3) {</span></span>
<span class="line"><span>        print(i);</span></span>
<span class="line"><span>        i = i + 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>验收：</strong> 输出 0、1、2，各占一行；将条件改为 <code>i &lt; 0</code> 时无输出。循环每次回到条件计算开始，不能跳回 JZ 本身，也不能重复执行 <code>let i=0</code>。查看 <code>--bytecode</code>，指出前向退出边与后向循环边。</p><p><strong>短路扩展：</strong> <code>false &amp;&amp; (1/0 == 1)</code> 输出 false，不触发除零；<code>true || (1/0 == 1)</code> 输出 true。这里不能先生成左右两侧，再做普通 AND/OR。对比 <code>Generator::expr</code> 对 <code>&amp;&amp;</code>、<code>||</code> 的两个布局，并画出到达右侧表达式的条件。</p><h2 id="实验-6-函数帧与递归" tabindex="-1">实验 6：函数帧与递归 <a class="header-anchor" href="#实验-6-函数帧与递归" aria-label="Permalink to &quot;实验 6：函数帧与递归&quot;">​</a></h2><p><strong>先实现：</strong> 先建函数签名表，再分析函数体；调用时建立新的局部变量数组和操作数栈。参数槽从 0 开始。调用者从左到右压参数，CALL 按相反顺序弹出并恢复形参顺序。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fn subtract(a: int, b: int) -&gt; int { return a - b; }</span></span>
<span class="line"><span>fn main() -&gt; int {</span></span>
<span class="line"><span>    print(subtract(8, 3));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>验收：</strong> 结果为 5，不能是 -5。随后运行 <code>examples/fibonacci.spr</code>，第十个输出为 34。递归各层的 n 必须独立；把局部变量数组错误地共享后，可观察递归结果如何受破坏。</p><p><strong>静态检查：</strong> 参数数目、类型、返回类型必须在执行前验证。<code>if/else</code> 两侧都 return 可证明返回；只有单侧 return 还不够。返回检查是保守分析，不能把“这次测试碰巧会返回”当作所有输入都返回的证明。</p><h2 id="实验-7-让错误可以复现、可以定位" tabindex="-1">实验 7：让错误可以复现、可以定位 <a class="header-anchor" href="#实验-7-让错误可以复现、可以定位" aria-label="Permalink to &quot;实验 7：让错误可以复现、可以定位&quot;">​</a></h2><p><strong>先实现：</strong> <code>Error</code>、检查算术、执行预算。错误不是 0 或其他普通值，不能继续参与计算。</p><p>分别写出并执行：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fn main()-&gt;int { print(2147483647 + 1); return 0; }</span></span>
<span class="line"><span>fn main()-&gt;int { print(7 / 0); return 0; }</span></span>
<span class="line"><span>fn main()-&gt;int { while(true){} return 0; }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>上面三行是三个独立文件，不能放在同一程序中，因为会重复定义 main。预期分别报溢出、除零、超过执行步数。第三个示例不会永远挂住。</p><p><strong>验收：</strong> <code>--check</code> 对这些示例均通过，因为没有静态类型问题；实际执行才失败。对 <code>let n=1; n=true;</code>，<code>--check</code> 必须失败且不能先执行 print。运行全部测试，核对静态错误和运行错误边界。</p><p><strong>边界题：</strong> 为什么 int32 乘法需要先转 int64 再相乘？为什么只在赋值到 int64 时转型来不及？<code>int64_t result = int32_a * int32_b;</code> 的乘法究竟以什么类型完成？</p><h2 id="实验-8-另一种后端与差分测试" tabindex="-1">实验 8：另一种后端与差分测试 <a class="header-anchor" href="#实验-8-另一种后端与差分测试" aria-label="Permalink to &quot;实验 8：另一种后端与差分测试&quot;">​</a></h2><p><strong>先实现：</strong> 将经过 Checker 标注的 AST 转换成独立 C++11 源码。用临时变量保存各子表达式，确保从左到右求值。生成目标代码不意味着调用 <code>system()</code> 执行用户字符串；本实现只输出文本，由用户明确运行工具链。</p><p>先运行 <code>--emit-cpp</code>，再用 g++ 编译生成文件。用 <code>examples/short-circuit.spr</code> 比较 VM 与本机程序，输出都应为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>false</span></span>
<span class="line"><span>true</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span>true</span></span>
<span class="line"><span>4</span></span>
<span class="line"><span>true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>验收：</strong> 使用 <code>python tests/run_tests.py ./sprout --native g++</code>，成功路径、溢出与除零等异常路径都应一致。测试包含有副作用的实参，能发现错误依赖 C++11 实参求值顺序的问题。资源预算采用不同粒度，接近上限的程序不作逐步等价比较。</p><p><strong>后续任务：</strong> 在 Checker 和后端之间加入三地址 IR；分基本块、构建控制流图，再实现有严格适用条件的常量折叠。保留原 VM 与未优化版本作为对照，不以单个速度测试取代语义正确性测试。LLVM、寄存器分配与直接机器码后端属于网站进阶路线，不是这八个实验的前置条件。</p>`,49)])])}const m=n(t,[["render",i]]);export{u as __pageData,m as default};
